   const payload={company_id:companyId,first_name:row.first_name.trim(),last_name:row.last_name.trim(),name:[row.first_name,row.last_name].filter(Boolean).join(" ").trim(),email:row.email||null,cell_phone:row.cell_phone||null,address:row.address||null,city:row.city||null,province:row.province||"ON",postal_code:row.postal_code||null,reco_license_number:row.reco_license_number||null,reco_license_expiry:row.reco_license_expiry||null,hst_number:row.hst_number||null,start_date:row.start_date||null,legal_name:row.legal_name||null,branch_id:branch?.id||null};
